-- Seller task proposals: Arthur's deterministic suggestions and owner decisions.
-- Bitrix24 remains the only seller-facing task manager; this module stores
-- proposals, decisions, and history for the owner inside the portal.

CREATE TABLE IF NOT EXISTS business_kpi.seller_task_library (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code text NOT NULL UNIQUE,
  task_type text NOT NULL CHECK (task_type IN ('STORE', 'KNOWLEDGE', 'SALES')),
  title text NOT NULL,
  description text NOT NULL,
  expected_result text NOT NULL,
  category text NOT NULL,
  material_text text,
  questions jsonb,
  active boolean NOT NULL DEFAULT true,
  sort_order integer NOT NULL DEFAULT 0
);

CREATE INDEX IF NOT EXISTS business_kpi_task_library_type_lookup
  ON business_kpi.seller_task_library(task_type, sort_order);

CREATE TABLE IF NOT EXISTS business_kpi.seller_task_proposals (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  store_id uuid NOT NULL REFERENCES business_kpi.stores(id),
  employee_id uuid NOT NULL REFERENCES business_kpi.employees(id),
  shift_date date NOT NULL,
  library_task_id uuid REFERENCES business_kpi.seller_task_library(id),
  task_type text NOT NULL CHECK (task_type IN ('STORE', 'KNOWLEDGE', 'SALES')),
  title text NOT NULL,
  description text NOT NULL,
  expected_result text,
  reason text,
  source text NOT NULL DEFAULT 'ARTHUR' CHECK (source IN ('ARTHUR', 'MANUAL')),
  status text NOT NULL DEFAULT 'PENDING'
    CHECK (status IN ('PENDING', 'APPROVED', 'REJECTED', 'COMPLETED', 'NOT_COMPLETED')),
  bitrix_text text,
  created_by_user_id uuid REFERENCES business_kpi.users(id),
  decided_by_user_id uuid REFERENCES business_kpi.users(id),
  decided_at timestamptz,
  approved_at timestamptz,
  result_note text,
  result_marked_by_user_id uuid REFERENCES business_kpi.users(id),
  result_marked_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- Idempotency: one non-rejected assignment per seller + shift + library task.
CREATE UNIQUE INDEX IF NOT EXISTS business_kpi_task_proposal_identity
  ON business_kpi.seller_task_proposals(employee_id, shift_date, library_task_id)
  WHERE library_task_id IS NOT NULL AND status <> 'REJECTED';

CREATE INDEX IF NOT EXISTS business_kpi_task_proposals_store_status
  ON business_kpi.seller_task_proposals(store_id, status, shift_date DESC);
CREATE INDEX IF NOT EXISTS business_kpi_task_proposals_employee_history
  ON business_kpi.seller_task_proposals(employee_id, shift_date DESC);

GRANT ALL PRIVILEGES ON TABLE business_kpi.seller_task_library TO business_kpi_app;
GRANT ALL PRIVILEGES ON TABLE business_kpi.seller_task_proposals TO business_kpi_app;

INSERT INTO business_kpi.seller_task_library
  (code, task_type, title, description, expected_result, category, material_text, questions, active, sort_order)
VALUES
  ('STORE-01', 'STORE', 'Пустые места', 'Обойди торговый зал и проверь полки на пустые места. Отметь, где товар закончился или выкладка просела.', 'Список пустых мест по полкам: что закончилось и что можно пополнить из запаса.', 'магазин', NULL, NULL, true, 1),
  ('STORE-02', 'STORE', 'Ценники категории', 'Проверь ценники в назначенной категории: наличие, соответствие цене в системе, читаемость, правильное положение.', 'Все ценники на местах, цены совпадают, повреждённые заменены.', 'магазин', NULL, NULL, true, 2),
  ('STORE-03', 'STORE', 'Сроки категории', 'Проверь сроки годности товара в назначенной категории по графику контроля. Сначала смотри то, что проверяется реже.', 'Просроченного товара нет; товар со сроком ближе ⅓ до конца вынесен вперёд/отмечен.', 'магазин', NULL, NULL, true, 3),
  ('STORE-04', 'STORE', 'AWARD на полке', 'Проверь выкладку кормов AWARD: наличие основных линеек, ценники, чистоту полки, порядок по вкусам/типам.', 'Полка AWARD полная, ценники корректны, порядок восстановлен.', 'корма', NULL, NULL, true, 4),
  ('STORE-05', 'STORE', 'Влажные корма', 'Проверь полку влажных кормов: пустые места, ценники, порядок по брендам, сроки на фасадах.', 'Пустоты пополнены или зафиксированы, ценники и сроки в порядке.', 'корма', NULL, NULL, true, 5),
  ('STORE-06', 'STORE', 'Лакомства', 'Проверь полку лакомств: наличие, ценники, сроки, выкладка (висячие карманы и полки).', 'Полка лакомств в порядке, отсутствующие позиции перечислены.', 'лакомства', NULL, NULL, true, 6),
  ('STORE-07', 'STORE', 'Наполнители', 'Проверь полку наполнителей: пустые места, тяжёлые мешки в зоне доступа, ценники, порядок.', 'Полка пополнена, крупные фасоны удобно лежат, ценники корректны.', 'наполнители', NULL, NULL, true, 7),
  ('STORE-08', 'STORE', 'Паразитарка', 'Проверь товары от блох и клещей: наличие основных позиций, сроки годности, ценники, правильная зона хранения.', 'Ассортимент паразитарки в наличии, сроки и ценники проверены.', 'паразитарка', NULL, NULL, true, 8),
  ('STORE-09', 'STORE', 'Уход', 'Проверь полку средств ухода: шампуни, расчёски, когтерезы — наличие, ценники, чистота полки.', 'Полка ухода в порядке, отсутствующее перечислено.', 'уход', NULL, NULL, true, 9),
  ('STORE-10', 'STORE', 'Игрушки', 'Проверь игрушки: наличие, внешний вид упаковок, ценники, порядок в корзинах и на крючках.', 'Игрушки разложены по местам, повреждённые упаковки сняты, ценники на местах.', 'игрушки', NULL, NULL, true, 10),
  ('STORE-11', 'STORE', 'Одежда', 'Проверь одежду для животных: размерные ряды, ценники, порядок на вешалках, пустые крючки.', 'Одежда разложена по размерам, ценники корректны, пустоты зафиксированы.', 'одежда', NULL, NULL, true, 11),
  ('STORE-12', 'STORE', 'Туалеты и аксессуары', 'Проверь туалеты, лопатки, пакеты и аксессуары: наличие, ценники, порядок на полке.', 'Полка в порядке, отсутствующие позиции перечислены.', 'туалеты/аксессуары', NULL, NULL, true, 12),
  ('STORE-13', 'STORE', 'Медленный товар', 'Найди 3–5 позиций, которые двигаются медленнее всего. Проверь сроки, ценники и выкладку — возможно, товар «потерялся» на полке.', 'Список медленных позиций с примечанием: что проверено и что предложить владельцу.', 'магазин', NULL, NULL, true, 13),
  ('STORE-14', 'STORE', 'Товар дня', 'Выбери один товар дня из ассортимента. Проверь его наличие, ценник и место на полке. Будь готов рассказать о нём покупателям.', 'Товар дня выбран, полка и ценник в порядке, продавец может рассказать о товаре.', 'магазин', NULL, NULL, true, 14),
  ('STORE-15', 'STORE', 'Проверка маячков', 'Проверь назначенную группу товаров: наличие противокражных маячков и правильность установки.', 'По назначенной группе маячки установлены правильно; отклонения перечислены.', 'магазин', NULL, NULL, true, 15),
  ('STORE-16', 'STORE', 'Контроль маячков на кассе', 'Проверь соблюдение процесса снятия/деактивации маячков и их хранения на кассе.', 'Процесс на кассе соблюдается: маячки снимаются, деактивируются и хранятся правильно.', 'магазин', NULL, NULL, true, 16),
  ('KNOW-01', 'KNOWLEDGE', 'AWARD Sterilized', 'Разберись, для каких кошек подходит линейка Sterilized и чем она отличается от обычных кормов.', 'Продавец может объяснить назначение линейки и предложить её подходящей кошке.', 'ветдиеты', 'Черновик (требует проверки владельцем). Корма линейки Sterilized ориентированы на стерилизованных кошек: обычно это контроль веса и поддержание мочевыводящей системы. Точное назначение и показания — по информации производителя на упаковке. Не ставим диагнозы: при симптомах направляем к ветеринару.', '["Для каких кошек подходит линейка Sterilized?","Чем корм для стерилизованных отличается от обычного?","Какой вопрос задать покупателю, чтобы понять, подходит ли линейка?"]'::jsonb, true, 17),
  ('KNOW-02', 'KNOWLEDGE', 'AWARD Monoprotein', 'Разберись, что такое монопротеиновый корм и кому его можно предложить.', 'Продавец может объяснить идею одного источника белка и назвать подходящую ситуацию.', 'корма', 'Черновик (требует проверки владельцем). Монопротеиновый корм содержит один источник животного белка. Покупатели выбирают его при чувствительном пищеварении или желании исключить конкретный белок. Это не лечебный корм: при аллергии или симптомах направляем к ветеринару.', '["Что означает «монопротеиновый» корм?","В каких ситуациях покупатель может его искать?","Что ответить, если покупатель ждёт от корма лечебного эффекта?"]'::jsonb, true, 18),
  ('KNOW-03', 'KNOWLEDGE', 'AWARD Urinary / Veterinary Diet', 'Разберись, чем лечебные/диетические корма отличаются от обычных и как с ними работать.', 'Продавец знает границы: диетический корм назначает ветеринар, мы не подбираем лечение.', 'ветдиеты', 'Черновик (требует проверки владельцем). Ветеринарные диеты применяются по назначению ветеринара при конкретных состояниях. Продавец может рассказать о наличии линейки и правилах кормления по упаковке, но не подбирает диету и не отменяет назначения. Любые симптомы у животного — к ветеринару.', '["Кто назначает ветеринарную диету?","Что продавец может рассказать о диетическом корме, а что нет?","Как вежливо направить покупателя с симптомами к ветеринару?"]'::jsonb, true, 19),
  ('KNOW-04', 'KNOWLEDGE', 'Сухой или влажный корм', 'Разберись в различиях сухого и влажного кормления и в каких случаях что предлагать.', 'Продавец может помочь покупателю выбрать формат кормления и объяснить плюсы каждого.', 'корма', 'Черновик (требует проверки владельцем). Сухой корм удобен для самоконтроля порции и хранения; влажный даёт дополнительную влагу в рацион и часто вкуснее для привередливых животных. Многие владельцы комбинируют. Точные рекомендации по рациону — по информации производителя и консультации ветеринара.', '["Какие плюсы сухого корма?","Какие плюсы влажного корма?","Какой вопрос задать, чтобы понять привычный режим кормления кошки?"]'::jsonb, true, 20),
  ('KNOW-05', 'KNOWLEDGE', 'Переход на новый корм', 'Разберись, как правильно переводить животное на другой корм.', 'Продавец объясняет постепенный переход и предупреждает о резкой смене корма.', 'корма', 'Черновик (требует проверки владельцем). Резкая смена корма часто вызывает проблемы с пищеварением. Обычно новый корм вводят постепенно, смешивая со старым и наращивая долю за 5–7 дней. Точную схему перехода покупатель берёт с упаковки корма или у ветеринара.', '["Почему нельзя резко менять корм?","Как выглядит постепенный переход?","Что посоветовать покупателю при чувствительном пищеварении у животного?"]'::jsonb, true, 21),
  ('KNOW-06', 'KNOWLEDGE', 'Лакомства', 'Разберись в видах лакомств и как выбрать подходящее.', 'Продавец предлагает лакомство под конкретную задачу: поощрение, чистка зубов, занятие.', 'лакомства', 'Черновик (требует проверки владельцем). Лакомства различаются по задаче: мягкие для поощрения, жевательные для занятия, функциональные (например, для гигиены полости рта). Важно помнить: лакомства — это дополнение к рациону, а не основной корм; количество по упаковке.', '["По каким задачам покупатель ищет лакомство?","Что предложить вместо «просто вкусняшки»?","Какой сопутствующий товар идёт вместе с лакомством?"]'::jsonb, true, 22),
  ('KNOW-07', 'KNOWLEDGE', 'Тофу или древесный наполнитель', 'Разберись, чем отличаются два типа наполнителя и в каких ситуациях какой вариант можно предложить покупателю.', 'Продавец может сравнить два типа и предложить вариант под ситуацию покупателя.', 'наполнители', 'Черновик (требует проверки владельцем). Тофу-наполнитель растительный, комкующийся, обычно тяжелее и дороже; древесный — впитывающий, рассыпается в опилки, часто дешевле. Выбор зависит от кошки, туалета, бюджета и предпочтений по уборке. Конкретные свойства — по упаковке производителя.', '["В чём основные различия?","Какие вопросы нужно задать покупателю?","Какой сопутствующий товар можно предложить?"]'::jsonb, true, 23),
  ('KNOW-08', 'KNOWLEDGE', 'Выбор наполнителя', 'Научись подбирать наполнитель по потребности: комкующийся, впитывающий, силикагель, растительный.', 'Продавец задаёт 2–3 вопроса и предлагает подходящий тип наполнителя.', 'наполнители', 'Черновик (требует проверки владельцем). Ключевые вопросы: сколько кошек, какой туалет (с сеткой или без), важна ли комкующесть, есть ли аллергия на пыль/ароматизаторы, какой бюджет. Комкующийся удобно убирать по комкам; впитывающий меняют целиком; силикагель держит запах дольше.', '["Какие 3 вопроса задать покупателю о наполнителе?","Чем комкующийся наполнитель отличается по уходу от впитывающего?","Когда стоит предложить силикагель?"]'::jsonb, true, 24),
  ('KNOW-09', 'KNOWLEDGE', 'Блохи и клещи', 'Разберись в средствах от блох и клещей: форматы, сезонность, базовые правила применения.', 'Продавец предлагает подходящий формат и направляет к ветеринару при сомнениях.', 'паразитарка', 'Черновик (требует проверки владельцем). Средства бывают каплями на холку, ошейниками, спреями, таблетками. Выбор зависит от животного, возраста, веса и образа жизни. Мы не назначаем препараты: дозировка и применение — строго по инструкции производителя; при симптомах паразитарных заболеваний — к ветеринару.', '["Какие форматы средств от паразитов есть в магазине?","От чего зависит выбор средства?","Почему нельзя советовать препарат как лечение?"]'::jsonb, true, 25),
  ('KNOW-10', 'KNOWLEDGE', 'Шампуни', 'Разберись в шампунях для животных: обычные, для щенков/котят, специализированные.', 'Продавец подбирает шампунь под задачу и предупреждает о моющих средствах «не для животных».', 'уход', 'Черновик (требует проверки владельцем). Человеческие шампуни не подходят животным — другой pH кожи. Выбираем шампунь по виду шерсти, возрасту и задаче (например, для щенков или для частого применения). При кожных проблемах — только ветеринар.', '["Почему нельзя мыть животное человеческим шампунем?","По каким признакам подбираем шампунь?","Что ответить при вопросе про кожную проблему у животного?"]'::jsonb, true, 26),
  ('KNOW-11', 'KNOWLEDGE', 'Уход за шерстью', 'Разберись в расчёсках, колтунорезах, когтерезах и базовом груминге.', 'Продавец предлагает инструмент под тип шерсти и показывает логичное дополнение.', 'уход', 'Черновик (требует проверки владельцем). Длинношёрстным нужны расчёски и средства против колтунов; короткошёрстным — щётки/рукавицы. Когти подстригают когтерезом по правилам. Технику стрижки и обработку кожи не советуем — это грумер/ветеринар.', '["Какой инструмент подходит длинношёрстной кошке?","Что предложить покупателю щенка?","Какое дополнение логично к расчёске?"]'::jsonb, true, 27),
  ('KNOW-12', 'KNOWLEDGE', 'Игрушки для кошки', 'Разберись в игрушках для кошек: активные, интеллектуальные, мягкие, когтеточки.', 'Продавец предлагает игрушку под поведение кошки и возраст.', 'игрушки', 'Черновик (требует проверки владельцем). Охотничьим кошкам — игрушки «добыча» (мячики, мышки на верёвочке); скучающим дома — интеллектуальные с лакомством; активным — лазеры и трекеры. Лазер не направляем в глаза. Маленькие детали у котят — под наблюдением.', '["Какие игрушки подходят активной кошке?","Что предложить для кошки, которая много времени одна дома?","Какой сопутствующий товар предложить к игрушке?"]'::jsonb, true, 28),
  ('KNOW-13', 'KNOWLEDGE', 'Игрушки для собаки', 'Разберись в игрушках для собак: по размеру, типу игры и жевательной нагрузке.', 'Продавец подбирает игрушку по размеру и характеру собаки.', 'игрушки', 'Черновик (требует проверки владельцем). Игрушка подбирается по размеру собаки: слишком маленькая — опасна проглотить, слишком мягкая для жевателя — разорвётся. Жевательным собакам — прочные резиновые; для апортировки — мячи и канаты. Меняем игрушки, чтобы питомец не скучал.', '["Почему размер игрушки важен?","Что предложить собаке, которая грызёт всё?","Какой вопрос задать о характере собаки?"]'::jsonb, true, 29),
  ('KNOW-14', 'KNOWLEDGE', 'Амуниция', 'Разберись в шлейках, ошейниках и поводках: посадка, размеры, безопасность.', 'Продавец помогает подобрать амуницию по размеру и предлагает примерку.', 'амуниция', 'Черновик (требует проверки владельцем). Шлейка безопаснее ошейника для выгула: нагрузка распределяется на грудь. Размер измеряем по груди и шее. Для кошек — только шлейки «для кошек». Правильная посадка: два пальца между ремнями и телом.', '["Чем шлейка лучше ошейника для выгула?","Как понять, что шлейка сидит правильно?","Какой сопутствующий товар предложить к шлейке?"]'::jsonb, true, 30),
  ('KNOW-15', 'KNOWLEDGE', 'Одежда', 'Разберись в одежде для собак: размеры, сезоны, кому действительно нужна.', 'Продавец подбирает одежду по размеру и объясняет, кому она нужна.', 'одежда', 'Черновик (требует проверки владельцем). Одежда нужна короткошёрстным мелким породам на холод, крупным собакам с тонкой шерстью, пожилым животным. Размер — по длине спины и обхвату груди по таблице производителя. Натужную одежду не предлагаем.', '["Каким собакам одежда нужна больше всего?","Какие мерки нужны для подбора размера?","Какой сопутствующий товар предложить к одежде?"]'::jsonb, true, 31),
  ('KNOW-16', 'KNOWLEDGE', 'Витамины и добавки', 'Разберись, как грамотно рассказывать о витаминах и добавках, не обещая лечебного эффекта.', 'Продавец рассказывает о добавках как о рационе/поддержке и направляет к ветеринару при целях лечения.', 'витамины/добавки', 'Черновик (требует проверки владельцем). Витамины и добавки не являются лекарствами. Продавец может рассказать о составе по упаковке и о том, что добавки применяют по инструкции производителя. Любые цели лечения, подбор при болезнях и совместимость с лекарствами — только с ветеринаром.', '["Чем добавка отличается от лекарства?","Что мы можем рассказать покупателю, а чего нет?","Как ответить на просьбу «подобрать для лечения»?"]'::jsonb, true, 32),
  ('KNOW-17', 'KNOWLEDGE', 'Туалет для кошки', 'Разберись в типах туалетов и аксессуарах: лопатки, пакеты, дезодоранты, сетки.', 'Продавец предлагает туалет и аксессуары под тип наполнителя и кошку.', 'туалеты/аксессуары', 'Черновик (требует проверки владельцем). Открытые туалеты проще в уходе; закрытые лучше держат запах и подходят крупным кошкам при правильном размере. Для древесного наполнителя часто нужна сетка. Логичное дополнение: лопатка под тип наполнителя, пакеты для утилизации, дезодорант для туалета.', '["Когда предложить закрытый туалет?","Зачем нужна сетка в туалете?","Какие аксессуары предложить вместе с туалетом?"]'::jsonb, true, 33),
  ('KNOW-18', 'KNOWLEDGE', 'Новый товар', 'Изучи новинку ассортимента: назначение, отличия, кому подходит, какие вопросы задавать.', 'Продавец может рассказать о новинке и предложить её подходящему покупателю.', 'продажи', 'Черновик (требует проверки владельцем). Для изучения берётся конкретная новинка из текущего ассортимента: читаем упаковку/материалы производителя, пробуем сформулировать 3 отличия и 2 типа покупателей, которым товар подойдёт. Свойства не выдумываем — только то, что подтверждено материалами производителя.', '["Что это за товар и для кого он?","В чём его 3 главных отличия?","Какому покупателю сегодня его можно предложить?"]'::jsonb, true, 34),
  ('SALE-01', 'SALES', 'Наполнитель + дополнение', 'В каждом чеке с наполнителем предлагай логичное дополнение: лопатку, пакеты, дезодорант, совок.', 'В смене минимум 2 чека с наполнителем дополнены полезным товаром.', 'продажи', NULL, NULL, true, 35),
  ('SALE-02', 'SALES', 'Корм + дополнение', 'При продаже корма предлагай полезное дополнение: лакомство, влажный корм, мерный стакан, контейнер для хранения.', 'В смене минимум 2 кормовых чека дополнены сопутствующим товаром.', 'продажи', NULL, NULL, true, 36),
  ('SALE-03', 'SALES', 'Новый питомец', 'Когда покупатель говорит, что только что завёл питомца, собери базовый набор: корм, туалет/пелёнки, лакомство, игрушку, средство от паразитов по возрасту.', 'Умение собрать стартовый набор и объяснить, зачем нужна каждая позиция.', 'продажи', NULL, NULL, true, 37),
  ('SALE-04', 'SALES', 'Шампунь + уход', 'При продаже шампуня предлагай расчёску, полотенце или средство для ушей — по типу шерсти животного.', 'Каждый второй чек со шампунем дополнен товаром для ухода.', 'продажи', NULL, NULL, true, 38),
  ('SALE-05', 'SALES', 'Туалет комплектом', 'Продавай туалет комплектом: туалет + лопатка + пакеты + (при необходимости) сетка или дезодорант.', 'Умение предложить комплект одним предложением, а не списком позиций.', 'продажи', NULL, NULL, true, 39),
  ('SALE-06', 'SALES', 'Игрушка по потребности', 'Прежде чем предлагать игрушку, задай 1–2 вопроса о питомце (возраст, активность, что уже есть дома) и предложь подходящий вариант.', 'Покупатель уходит с игрушкой, подходящей его питомцу, а не случайной.', 'продажи', NULL, NULL, true, 40),
  ('SALE-07', 'SALES', 'Возражение «дорого»', 'Отработай ответ на возражение «дорого»: сравнение по составу/расходу, альтернатива дешевле, акция, или честное «это лучший вариант под задачу».', 'Продавец не теряется на возражении и предлагает осмысленный вариант, а не скидку.', 'продажи', NULL, NULL, true, 41),
  ('SALE-08', 'SALES', 'Три вопроса покупателю', 'Перед подбором товара задай покупателю минимум три уточняющих вопроса о питомце и ситуации.', 'Подбор строится на потребности: в смене минимум 3 диалога начинаются с уточняющих вопросов.', 'продажи', NULL, NULL, true, 42),
  ('SALE-09', 'SALES', 'Знаю альтернативу', 'Выучи сегодняшний топ-5 товаров категории и по каждому — одну дешевле и одну дороже альтернативу.', 'Продавец может предложить альтернативу без уточнения у коллег.', 'продажи', NULL, NULL, true, 43),
  ('SALE-10', 'SALES', 'Комплексная консультация', 'Отработай схему комплексной продажи: потребность → подбор → объяснение → полезное дополнение → следующий шаг для покупателя.', 'Консультация завершается дополнением к основной покупке в половине случаев.', 'продажи', NULL, NULL, true, 44)
ON CONFLICT (code) DO NOTHING;
